//! ODS attribute constraints: what `verifyInherentAttrs` checks of an op's inherent attributes
//! while `mlir-opt` reads it (`ods.gen.rs`, generated by `scripts/traits.py`).

use crate::{Attribute, Signedness, Type};

#[path = "ods.gen.rs"]
mod table;

/// An integer constraint's signedness.
#[derive(Clone, Copy)]
pub(super) enum Sign {
    Signless,
    Signed,
    Unsigned,
    /// Any of the three (`AnyI32Attr`).
    Any,
}

/// The element of a dense array or elements attribute.
#[derive(Clone, Copy)]
pub(super) enum Elem {
    /// A signless integer of this width.
    Int(u32),
    /// An integer of this width, any signedness.
    AnyInt(u32),
    Float(u32),
    Index,
}

/// A dense array's order (`DenseArrayStrictlySorted`, `DenseArraySorted`).
#[derive(Clone, Copy)]
pub(super) enum Order {
    Increasing,
    NonDecreasing,
}

/// What a `TypeAttrOf<..>` holds.
#[derive(Clone, Copy)]
pub(super) enum TypeOf {
    LlvmFunction,
    Function,
}

/// ⭐ One inherent attribute's ODS constraint.
pub(super) enum C {
    /// `I32Attr`, `SI32Attr`, `AnyI64Attr`, a `ConfinedAttr` with `IntNonNegative` /
    /// `IntPositive` (`min`), an `I32EnumAttr` (`cases`).
    Int { width: u32, sign: Sign, min: Option<i64>, cases: Option<&'static [i64]> },
    Index,
    Float(u32),
    Bool,
    Str,
    Unit,
    Type(Option<TypeOf>),
    TypeArray,
    FlatSymbolRef,
    SymbolRef,
    DenseArray { elem: Elem, order: Option<Order>, min: Option<i64> },
    Elements { elem: Elem, shape: Option<&'static [i64]> },
    AnyOf(&'static [C]),
    /// A dialect's `EnumAttr`: `#spirv.memory_access<..>` (its full name).
    Dialect(&'static str),
}

/// ⭐ The kind of one operand or result type: the C++ class its ODS constraint is of
/// (`::mlir::VectorType`), or a summary read (`bool`).
#[derive(Clone, Copy)]
pub(super) enum K {
    /// Not checked.
    Any,
    Integer,
    Index,
    Float,
    Vector,
    Tensor,
    MemRef,
    /// `i1`.
    Bool,
    /// `i1` or a vector of 2, 3, 4, 8 or 16 of them (`SPIRV_ScalarOrVectorOf<SPIRV_Bool>`).
    BoolLike,
}

impl K {
    /// Does type `t` fit? An alias (`!t`) does: what it names is not known here.
    pub(super) fn admits(self, t: &Type<'_>) -> bool {
        let shaped = |k: crate::ShapedKind| matches!(t, Type::Shaped(s) if s.kind == k);
        match (self, t) {
            (K::Any, _) => true,
            (_, Type::Extended(e)) if !e.name.contains('.') => true,
            (K::Integer, Type::Integer { .. }) | (K::Index, Type::Index) | (K::Float, Type::Float(_)) => true,
            (K::Vector, _) => shaped(crate::ShapedKind::Vector),
            (K::Tensor, _) => shaped(crate::ShapedKind::Tensor),
            (K::MemRef, _) => shaped(crate::ShapedKind::MemRef),
            (K::Bool, _) => *t == Type::I1,
            (K::BoolLike, Type::Shaped(s)) => s.kind == crate::ShapedKind::Vector && *s.elem == Type::I1 && s.shape.as_deref().is_some_and(|d| matches!(d, [crate::Dim::Static(2 | 3 | 4 | 8 | 16)])),
            (K::BoolLike, _) => *t == Type::I1,
            _ => false,
        }
    }

    /// Op `name`'s operand and result kinds.
    pub(super) fn of_op(name: &str) -> (Option<&'static [K]>, Option<&'static [K]>) {
        table::KINDS.binary_search_by(|(n, _, _)| (*n).cmp(name)).map_or((None, None), |i| (table::KINDS[i].1, table::KINDS[i].2))
    }
}

/// An integer literal's value (`5`, `-5`, `0x1F`).
fn value(lit: &str) -> Option<i128> {
    let (neg, digits) = lit.strip_prefix('-').map_or((false, lit), |d| (true, d));
    let v = match digits.strip_prefix("0x") {
        Some(h) => i128::from_str_radix(h, 16).ok()?,
        None => digits.parse().ok()?,
    };
    Some(if neg { -v } else { v })
}

impl Elem {
    /// Does element type `t` fit?
    fn admits(self, t: &Type<'_>) -> bool {
        match (self, t) {
            (Elem::Int(w), Type::Integer { signedness: Signedness::Signless, width }) | (Elem::AnyInt(w), Type::Integer { width, .. }) => *width == w,
            (Elem::Float(w), Type::Float(_)) => t.bit_width() == Some(w),
            (Elem::Index, Type::Index) => true,
            _ => false,
        }
    }
}

impl Sign {
    #[inline]
    fn admits(self, s: Signedness) -> bool {
        matches!((self, s), (Sign::Any, _) | (Sign::Signless, Signedness::Signless) | (Sign::Signed, Signedness::Signed) | (Sign::Unsigned, Signedness::Unsigned))
    }
}

impl C {
    /// Does attribute `a` (`None`: a unit attribute written by its name alone) satisfy it?
    pub(super) fn admits(&self, a: Option<&Attribute<'_>>) -> bool {
        let a = match a {
            None | Some(Attribute::Unit) => return matches!(self, C::Unit | C::AnyOf(_)) && self.admits_unit(),
            Some(a) => a,
        };
        match (self, a) {
            (C::Int { width, sign, min, cases }, Attribute::Int { lit, ty }) => {
                let (s, w) = match ty {
                    None => (Signedness::Signless, 64),
                    Some(Type::Integer { signedness, width }) => (*signedness, *width),
                    Some(_) => return false,
                };
                let Some(v) = value(lit) else { return true };
                // A case is matched on the value's bits (`2147483648` is `-2147483648 : i32`).
                let bits = |x: i128| if *width >= 128 { x } else { x & ((1i128 << width) - 1) };
                sign.admits(s) && w == *width && min.is_none_or(|m| v >= i128::from(m)) && cases.is_none_or(|cs| cs.iter().any(|c| bits(i128::from(*c)) == bits(v)))
            }
            (C::Int { width: 1, .. }, Attribute::Bool(_)) | (C::Bool, Attribute::Bool(_)) => true,
            (C::Index, Attribute::Int { ty: Some(Type::Index), .. }) => true,
            (C::Float(w), Attribute::Float { ty, .. }) => ty.as_ref().map_or(Some(64), Type::bit_width) == Some(*w),
            (C::Str, Attribute::Str { ty: None, .. }) => true,
            (C::Type(None), Attribute::Type(_)) => true,
            (C::Type(Some(TypeOf::LlvmFunction)), Attribute::Type(Type::Extended(e))) => e.name == "llvm.func",
            (C::Type(Some(TypeOf::Function)), Attribute::Type(Type::Function(_))) => true,
            (C::TypeArray, Attribute::Array(xs)) => xs.iter().all(|x| matches!(x, Attribute::Type(_))),
            (C::FlatSymbolRef, Attribute::SymbolRef(s)) => s.len() == 1,
            (C::SymbolRef, Attribute::SymbolRef(_)) => true,
            (C::DenseArray { elem, order, min }, Attribute::DenseArray { ty, values }) => {
                let vs: Option<alloc::vec::Vec<i128>> = values.iter().map(|v| value(v)).collect();
                elem.admits(ty)
                    && vs.is_none_or(|vs| {
                        min.is_none_or(|m| vs.iter().all(|v| *v >= i128::from(m)))
                            && match order {
                                Some(Order::Increasing) => vs.windows(2).all(|p| p[0] < p[1]),
                                Some(Order::NonDecreasing) => vs.windows(2).all(|p| p[0] <= p[1]),
                                None => true,
                            }
                    })
            }
            (C::Elements { elem, shape }, Attribute::Builtin { name, ty: Some(t @ Type::Shaped(s)), .. }) if matches!(&**name, "dense" | "dense_resource" | "sparse") => {
                let dims = s.shape.as_ref().map(|d| d.iter().map(|d| if let crate::Dim::Static(n) = d { *n } else { -1 }).collect::<alloc::vec::Vec<i64>>());
                elem.admits(t.element_type()) && shape.is_none_or(|want| dims.as_deref() == Some(want))
            }
            (C::AnyOf(cs), a) => cs.iter().any(|c| c.admits(Some(a))),
            // Itself, or an alias (`#mode`).
            (C::Dialect(name), Attribute::Extended { ext, .. }) => ext.name == *name || !ext.name.contains('.'),
            // An alias (`#map`) or a dialect attribute: what it stands for is not known here.
            (_, Attribute::Extended { .. }) => true,
            _ => false,
        }
    }

    /// May a unit attribute stand for it?
    fn admits_unit(&self) -> bool {
        match self {
            C::Unit => true,
            C::AnyOf(cs) => cs.iter().any(C::admits_unit),
            _ => false,
        }
    }

    /// Op `name`'s inherent attributes with their constraints.
    pub(super) fn of_op(name: &str) -> &'static [(&'static str, C)] {
        table::OPS.binary_search_by(|(n, _)| (*n).cmp(name)).map_or(&[], |i| table::OPS[i].1)
    }
}
